  void render(){if(list==null)return;if(isThreadListFilter(filter)){otherScroll.setVisibility(View.GONE);threadsRecycler.setVisibility(View.VISIBLE);emptyThreadsView.setVisibility(View.GONE);loadThreadRows();return;}threadHandler.removeCallbacks(threadRefreshRunnable);threadHandler.removeCallbacks(searchFilterRunnable);threadsRecycler.setVisibility(View.GONE);emptyThreadsView.setVisibility(View.GONE);otherScroll.setVisibility(View.VISIBLE);list.removeAllViews();if("trash".equals(filter)){trashScreen();return;}if("starred".equals(filter)){starredScreen();return;}if("bulk".equals(filter)){bulkScreen();return;}if("groups".equals(filter)){groupsScreen();return;}if("rules".equals(filter)){forwardRulesScreen();return;}if("scheduled".equals(filter)){scheduledScreen();return;}if("failed".equals(filter)){failedScreen();return;}}
  void loadThreadRows(){if(!isThreadListFilter(filter)||isFinishing()||isDestroyed())return;final String requestedFilter=filter;final long generation=++threadGeneration;if(pendingThreadsLoad!=null)pendingThreadsLoad.cancel(true);pendingThreadsLoad=DATA_EXECUTOR.submit(()->{ArrayList<ThreadItem> rows=new ArrayList<>();android.database.Cursor c=null;try{c=db.listThreads(requestedFilter);while(c.moveToNext()){if(Thread.currentThread().isInterrupted())return;String address=c.getString(c.getColumnIndexOrThrow("address"));String body=c.getString(c.getColumnIndexOrThrow("body"));String status=c.getString(c.getColumnIndexOrThrow("status"));long stamp=0;try{stamp=Long.parseLong(c.getString(c.getColumnIndexOrThrow("ts")));}catch(Exception ignored){}ContactData contact=loadContactData(address);rows.add(new ThreadItem(address,body==null?"":body,status==null?"":status,stamp,contact.name,contact.photo));}}catch(Exception e){android.util.Log.e("HashemSMS","Unable to load conversation list",e);}finally{if(c!=null)c.close();}if(Thread.currentThread().isInterrupted())return;runOnUiThread(()->{if(generation!=threadGeneration||!isThreadListFilter(filter)||!requestedFilter.equals(filter)||isFinishing()||isDestroyed())return;allThreadItems=rows;applyThreadSearch();});});}
  void applyThreadSearch(){if(!isThreadListFilter(filter)||isFinishing()||isDestroyed())return;final String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);final long generation=++filterGeneration;final ArrayList<ThreadItem> snapshot=new ArrayList<>(allThreadItems);if(pendingFilterTask!=null)pendingFilterTask.cancel(true);pendingFilterTask=DATA_EXECUTOR.submit(()->{ArrayList<ThreadItem> result=new ArrayList<>();for(ThreadItem item:snapshot){if(Thread.currentThread().isInterrupted())return;if(query.isEmpty()||item.address.toLowerCase(Locale.ROOT).contains(query)||item.body.toLowerCase(Locale.ROOT).contains(query)||item.contact.toLowerCase(Locale.ROOT).contains(query))result.add(item);}runOnUiThread(()->{if(generation!=filterGeneration||!isThreadListFilter(filter)||isFinishing()||isDestroyed())return;threadAdapter.submitList(result);emptyThreadsView.setVisibility(result.isEmpty()?View.VISIBLE:View.GONE);});});}
  ContactData loadContactData(String number){String name;Uri photo;android.graphics.Bitmap bitmap;synchronized(contactCache){name=contactCache.get(number);}synchronized(contactPhotoCache){photo=contactPhotoCache.get(number);}synchronized(contactBitmapCache){bitmap=contactBitmapCache.get(number);}if(name==null){name="";android.database.Cursor cursor=null;try{Uri uri=Uri.withAppendedPath(ContactsContract.PhoneLookup.CONTENT_FILTER_URI,Uri.encode(number));cursor=getContentResolver().query(uri,new String[]{ContactsContract.PhoneLookup.DISPLAY_NAME,ContactsContract.PhoneLookup.PHOTO_THUMBNAIL_URI},null,null,null);if(cursor!=null&&cursor.moveToFirst()){String found=cursor.getString(0);name=found==null?"":found;String raw=cursor.getString(1);if(raw!=null&&!raw.trim().isEmpty())photo=Uri.parse(raw);}}catch(Exception e){android.util.Log.w("HashemSMS","Contact lookup failed",e);}finally{if(cursor!=null)cursor.close();}synchronized(contactCache){contactCache.put(number,name);}if(photo!=null)synchronized(contactPhotoCache){contactPhotoCache.put(number,photo);}}
   if(bitmap==null&&photo!=null){java.io.InputStream in=null;try{in=getContentResolver().openInputStream(photo);if(in!=null)bitmap=android.graphics.BitmapFactory.decodeStream(in);}catch(Exception e){android.util.Log.w("HashemSMS","Contact photo load failed",e);}finally{if(in!=null)try{in.close();}catch(Exception ignored){}}if(bitmap!=null)synchronized(contactBitmapCache){contactBitmapCache.put(number,bitmap);}}
   return new ContactData(name==null?"":name,bitmap);}
