  final class ThreadViewHolder extends androidx.recyclerview.widget.RecyclerView.ViewHolder{final LinearLayout row,avatar,details,meta,container;final ImageView photo;final TextView fallback,name,body,status,time;ThreadViewHolder(LinearLayout outer,LinearLayout row,LinearLayout avatar,ImageView photo,TextView fallback,TextView name,TextView body,LinearLayout meta,TextView status,TextView time){super(outer);this.container=outer;this.row=row;this.avatar=avatar;this.photo=photo;this.fallback=fallback;this.name=name;this.body=body;this.meta=meta;this.status=status;this.time=time;this.details=(LinearLayout)row.getChildAt(1);}}
