   @Override public void onBindViewHolder(ThreadViewHolder h,int position){ThreadItem item=getItem(position);h.name.setText(item.contact.isEmpty()?item.address:item.contact);h.body.setText(item.body);h.status.setText(item.status);h.time.setText(item.timestamp>0?new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(item.timestamp)):"");if(item.photo!=null){h.photo.setImageBitmap(item.photo);h.photo.setVisibility(View.VISIBLE);h.fallback.setVisibility(View.GONE);}else{h.photo.setImageDrawable(null);h.photo.setVisibility(View.GONE);h.fallback.setText(item.contact.isEmpty()?item.address:item.contact);h.fallback.setTextSize(!item.contact.isEmpty()&&item.contact.length()>9?7:9);if(h.avatar.getChildCount()>1)h.avatar.removeViewAt(1);if(h.avatar.indexOfChild(h.fallback)<0)h.avatar.addView(h.fallback,new LinearLayout.LayoutParams(-1,-1));h.fallback.setVisibility(View.VISIBLE);}h.row.setOnClickListener(v->{Intent i=new Intent(MainActivity.this,ConversationActivity.class);i.putExtra("address",item.address);startActivity(i);});h.row.setOnLongClickListener(v->{PopupMenu menu=new PopupMenu(MainActivity.this,h.row);boolean archived="archived".equals(filter),blocked="blocked".equals(filter);menu.getMenu().add(archived?"إلغاء الأرشفة":"أرشفة المحادثة");menu.getMenu().add(blocked?"إلغاء الحظر":"حظر الرقم");menu.setOnMenuItemClickListener(action->{String label=action.getTitle().toString();DATA_EXECUTOR.execute(()->{if("أرشفة المحادثة".equals(label)||"إلغاء الأرشفة".equals(label))db.setConversationFlag(item.address,"archived","أرشفة المحادثة".equals(label));else if("حظر الرقم".equals(label)||"إلغاء الحظر".equals(label))db.setConversationFlag(item.address,"blocked","حظر الرقم".equals(label));runOnUiThread(()->{if(isThreadListFilter(filter))loadThreadRows();});});return true;});menu.show();return true;});}
